import { useState } from 'react';
const DEFAULT_MEMBERS = [{id:'local', name:'Local', role:'member'}];
async function fetchApi(url: string, init?: RequestInit) {
  const res = await fetch(url, init);
  if (!res.ok) {
    let errorBody: { error?: string; details?: string } = {};
    try {
      errorBody = await res.json();
    } catch {
      errorBody = { error: `HTTP ${res.status}` };
    }
    throw new Error(
      errorBody.error || `HTTP ${res.status}`
    );
  }
  return res.json();
}


async function read() { const [members, setMembers] = useState(DEFAULT_MEMBERS); const data = await fetchApi('/api/projects'); if (Array.isArray(data.members)) setMembers(data.members); return members; }

